"""Matched legacy slots get new questions but retain the existing scored letter."""
from content_core import *
def questions():
 g=[]
 def a(stem,val,oracle,work,wr):
  g.append(item(10,'geometry-repair',len(g)+1,GEO,'Geometry and measurement',min(5,2+len(g)//12),stem,val,oracle,work,wr))
 a('A 6 by 10 rectangle is cut into two equal rectangles by a straight cut parallel to its shorter sides. What is the sum of the two new perimeters?',44,2*(6+10)+2*6,'The original perimeter is 32. The 6-unit cut appears once on each new boundary, adding 12 for a total of 44.',[32,38,48,52])
 a('An isosceles triangle has sides 13,13,10. What is the distance from its apex to the midpoint of its base?',12,math.isqrt(13**2-5**2),'The median from the apex bisects the base and is perpendicular to it. A right triangle has hypotenuse 13 and one leg 5, so the other leg is 12.',[5,8,10,13])
 a('A wheel of radius 6 rolls without slipping through three quarters of a revolution. The distance its centre travels is kπ. What is k?',9,2*6*F(3,4),'One revolution covers the circumference 12π. Three quarters covers 9π.',[6,8,12,18])
 a('On one straight line, B lies between A and C, and C lies between B and D. If AC=11, BD=13 and AD=19, what is BC?',5,next(x for x in range(1,12) if (11-x)+x+(13-x)==19),'AC+BD counts the whole AD once and their overlap BC once more. Thus BC=11+13−19=5.',[3,4,6,8])
 a('An axis-parallel rectangle has three corners (−2,3), (5,3), (5,−1). What is the square of its diagonal length?',65,(5+2)**2+(3+1)**2,'The horizontal difference is 7 and the vertical difference is 4. The Pythagorean theorem gives 49+16=65.',[11,33,49,81])
 a('A walking track has two straight sides of length 20 and two semicircular ends of diameter 10. Its enclosed area is 200+kπ. Find k.',25,F(10**2,4),'The straight section is a 20 by 10 rectangle. Together the two semicircles make a radius-5 disk, contributing 25π.',[5,10,50,100])
 a('In triangle PQR, a line joins the midpoints of PQ and PR. The perimeter of the smaller triangle at P is 18. What is the perimeter of PQR?',36,F(18,1)/F(1,2),'The midpoint segment is parallel to QR, making a similar triangle with every side half as long. Double 18 to get 36.',[24,27,30,54])
 a('A square of area 18 is drawn with its diagonal horizontal. What is the distance between its two farthest vertices?',6,math.isqrt(2*18),'In a square, diagonal squared is twice side squared. Since side squared is the area 18, the diagonal is √36=6.',[3,9,12,18])
 a('A rectangular box has face areas 12,18 and 24 at one corner. What is the square of its volume?',5184,12*18*24,'If sides are a,b,c, multiplying ab,bc,ca gives (abc)². Thus the squared volume is 12×18×24=5184.',[1296,2592,3888,10368])
 a('A right triangle has legs 9 and 12. What is the altitude from its right angle to its hypotenuse?',F(36,5),F(9*12,math.isqrt(9**2+12**2)),'The hypotenuse is 15. Both 9×12/2 and 15h/2 are the same area, so h=108/15=36/5.',[6,F(15,2),8,9])
 a('A rhombus has diagonals 10 and 24. A circle is tangent to all four sides. What is its radius?',F(60,13),F(10*24,4*13),'The half-diagonals form a 5–12–13 triangle, so the semiperimeter is 26. The area is 120 and equals inradius times semiperimeter. Hence r=60/13.',[4,5,F(120,13),6])
 a('A chord 16 units long in a circle of radius 10 lies above its centre. How far from the centre is the midpoint of the chord?',6,math.isqrt(100-64),'The radius to a chord midpoint is perpendicular. Half the chord is 8, so the distance is √(10²−8²)=6.',[2,4,8,10])
 a('A circle is tangent to both coordinate axes in the first quadrant and has centre on the line x+y=14. What is its diameter?',14,next(2*r for r in range(1,30) if r+r==14),'Tangency to both axes puts the centre at (r,r). Therefore 2r=14, already the diameter.',[7,12,21,28])
 a('A 20 by 12 rectangle is divided by joining one corner to the midpoints of the two opposite sides. What is the area of the triangle with these three vertices?',90,F(abs(20*12-6*10),2),'Take the corner at (0,0); the opposite midpoints are (20,6) and (10,12). Half the absolute determinant is (240−60)/2=90.',[60,75,100,120])
 a('In triangle ABC, D is on BC with BD:DC=2:5. If the altitude from A to line BC is 8 and triangle ACD has area 60, what is the area of ABD?',24,F(60*2,5),'The triangles have the same altitude, so their areas are in the same 2:5 ratio as the bases. The smaller area is 60×2/5=24.',[12,20,28,36])
 a('Two equal circles of radius 5 have centres 8 units apart. What is the length of their common chord?',6,2*math.isqrt(25-16),'The common chord bisects the line of centres perpendicularly. Its half-length is √(25−4²)=3; hence its full length is 6.',[3,4,8,10])
 a('A right circular cone has radius 5 and slant height 13. Its volume is kπ. What is k?',100,F(25*math.isqrt(13**2-5**2),3),'The axial right triangle gives vertical height 12. The volume is one third of π×25×12, giving 100π.',[60,65,125,300])
 a('A square has vertices (0,0),(8,0),(8,8),(0,8). A point P=(t,2) is equally distant from (0,0) and (8,8). What is t?',6,next(t for t in range(9) if t*t+4==(8-t)**2+36),'Equate squared distances: t²+4=(8−t)²+36. Cancel t²; 16t=96, so t=6.',[2,4,5,7])
 a('From a point outside a circle a tangent has length 12. A secant from the same point has an exterior segment of 8. What is the length strictly inside the circle on that secant?',10,F(12**2,8)-8,'Power of a point gives 12²=8 times the whole secant length, so the whole length is 18. Subtract 8 to get 10.',[8,12,16,18])
 a('A square’s vertices lie on a circle. Another square is made by joining the midpoints of the first. What fraction of the circle’s area is the smaller square’s area, expressed as k/π? Give k.',1,F(2,2),'If the circle radius is r, the first square has diagonal 2r and area 2r². Its midpoint square has half that area, r². Dividing by πr² gives 1/π.',[F(1,2),F(2,3),F(3,2),2])
 a('A map is enlarged so its area increases by 69%. A road that was 20 cm long on the map becomes how many centimetres long?',26,math.isqrt(20**2*169//100),'Lengths scale by the square root of the area factor. The length factor is √1.69=1.3, and 20×1.3=26.',[23,29,32,34])
 a('Three sides of a triangle have lengths 7,10 and x, where x is an integer. How many distinct values of x are possible?',13,sum(abs(10-7)<x<17 for x in range(1,30)),'Strict triangle inequalities require 3<x<17, so the integers 4 through 16 give 13 possibilities.',[12,14,15,16])
 a('A 60° sector has arc length 4π. What is its radius?',12,F(4*360,2*60),'The sector is one sixth of a circle. The full circumference is 24π; dividing by 2π gives radius 12.',[4,6,8,24])
 a('A sphere of radius 3 and a right cylinder of radius 2 have equal volumes. What is the height of the cylinder?',9,F(4*3**3,3*2**2),'The sphere volume is 36π and the cylinder volume is 4πh. Equating gives h=9.',[6,8,12,18])
 a('A line with positive slope passes through (2,1) and cuts the positive x-axis at x=1. What is the square of the distance from the origin to this line?',F(1,2),F((1-0)**2,1**2+1**2),'The line through (1,0) and (2,1) is x−y−1=0. The distance is |−1|/√2, whose square is 1/2.',[F(1,4),1,2,4])
 a('On a cube of side 6 an ant moves from one corner to the opposite corner across exactly two adjacent faces, taking a shortest route. What is the square of its route length?',180,(2*6)**2+6**2,'Unfold the two faces as a 12 by 6 rectangle. The straight diagonal is shortest, with squared length 144+36=180.',[108,144,216,324])
 a('An equilateral triangle has side 8. A smaller equilateral triangle is formed by joining the trisection points chosen one third of the way around each side in cyclic order. What fraction of the large triangle’s area is inside the smaller?',F(1,3),1-3*F(1,3)*F(2,3),'Each removed corner triangle has adjacent side lengths in the proportions 1/3 and 2/3 of the original pair with the same included angle, so each occupies 2/9 of the area. Subtract 3×2/9 from 1 to get 1/3.',[F(1,9),F(2,9),F(4,9),F(2,3)])
 a('A rectangle of perimeter 30 has integer side lengths. Among all such rectangles, what is the difference between the greatest and least possible areas?',42,max(t*(15-t) for t in range(1,15))-min(t*(15-t) for t in range(1,15)),'The side sum is 15. Closest sides 7,8 give area 56; most unequal sides 1,14 give 14. The difference is 42.',[28,35,49,56])
 a('Two similar solid pyramids have volumes in ratio 27:125. The larger pyramid has surface area 200. What is the surface area of the smaller?',72,200*F(3,5)**2,'The length ratio is the cube root, 3:5. Areas scale as 9:25, so 200×9/25=72.',[54,90,108,120])
 a('A circle of radius 5 is centred at (0,0). The line y=3 cuts the circle at A and B. What is the area of triangle OAB?',12,F(2*math.isqrt(25-9)*3,2),'The intersection coordinates have x=±4 because x²+9=25. AB has length 8 and altitude from O is 3, giving area 12.',[6,8,16,24])
 a('A right triangle has hypotenuse 25 and one leg 7. A square is drawn on its other leg. What is the area of that square?',576,25**2-7**2,'The square’s area is the unknown leg squared. Pythagoras gives 625−49=576.',[324,484,600,625])
 a('The bases of a trapezoid are 6 and 14, and its height is 9. A line parallel to the bases is drawn one third of the height up from the shorter base. What is the length of that line?',F(26,3),6+F(1,3)*(14-6),'Width changes linearly between the bases. One third of the way from 6 toward 14 adds 8/3, giving 26/3.',[8,9,10,F(34,3)])
 a('The diagonals of a kite are perpendicular and measure 14 and 18. An enlarged copy has perimeter twice the original. What is the area of the copy?',504,F(14*18,2)*4,'The original area is half the product of the diagonals, 126. Doubling perimeter doubles every length and quadruples area, for 504.',[126,252,378,1008])
 a('A circular pond of radius 4 has a path of constant width around it. If the path has the same area as the pond, what is the square of the outside radius?',32,2*4**2,'The total disk has area twice the pond area, or 32π. Therefore its radius squared is 32.',[16,20,24,64])
 a('A parallelogram has adjacent side vectors (4,1) and (1,3). What is the sum of the squares of the lengths of its two diagonals?',54,sum(x*x+y*y for x,y in [(4+1,1+3),(4-1,1-3)]),'The parallelogram law gives twice the sum of squared side lengths: 2[(16+1)+(1+9)]=54.',[27,40,50,58])
 a('The medians of a triangle meet at G. If the region formed by G and one entire side has area 18, what is the area of the full triangle?',54,3*18,'The centroid is one third of the altitude above the given base, because it lies one third of the way from the base midpoint toward the opposite vertex. The smaller triangle has one third the full area. Thus the area is 54.',[36,45,60,72])
 a('Two towers stand on level ground 12 units apart. Their heights are 5 and 14. What is the length of the straight cable joining their tops?',15,math.isqrt(12**2+(14-5)**2),'The horizontal separation is 12 and the height difference is 9. Pythagoras gives √(144+81)=15.',[13,14,17,21])
 a('A rectangle is inscribed in a semicircle of radius 5 with its lower side on the diameter, and its two upper corners on the arc. If its width is 6, what is its area?',24,6*math.isqrt(25-3**2),'The upper corners are symmetric, each horizontally 3 from the centre. The radius forms a 3–4–5 triangle, so height is 4. Area=6×4=24.',[12,18,20,30])
 assert len(g)==38
 r1=item(10,'counting-repair',14,CNT,'Grouping with restrictions',3,'A set of seven different coloured tiles contains one gold tile and one silver tile. Four tiles are chosen. How many choices contain exactly one of gold and silver?',20,sum(((0 in z)!=(1 in z)) for z in combinations(range(7),4)),'Choose the special tile in two ways and choose three of the other five in C(5,3)=10 ways. Their product is 20.',[10,15,25,30])
 r2=item(10,'probability-repair',22,PRO,'Conditional distributions',4,'A fair coin selects a tray: heads selects one with two red and one white bead, tails selects one with one red and three white. One random bead is drawn. Given that it is red, what is the probability the coin showed heads?',F(8,11),(F(1,2)*F(2,3))/(F(1,2)*F(2,3)+F(1,2)*F(1,4)),'Of 24 equally weighted trials, expect 12 per tray. The first supplies 8 red outcomes and the second 3; conditional on a red bead, 8 of 11 outcomes came from heads.',[F(1,2),F(2,3),F(3,4),F(3,11)])
 return g+[r1,r2]
